(() => {
  const side = document.querySelector('.col-md-3').innerText.replace(/\n{2,}/g,'\n');
  const rows = Array.from(document.querySelectorAll('#history table tbody tr')).map(tr=>Array.from(tr.cells).map(td=>td.innerText.trim()));
  const h1 = document.querySelector('h1').innerText.trim();
  return {h1, sidebar: side, historyRows: rows};
})()

(() => {
  const tb = document.querySelector('#details') || document.querySelector('.tab-pane.active');
  const txt = tb? tb.innerText.replace(/\n{2,}/g,'\n') : 'no details pane';
  return {active: tb? tb.id : null, txt: txt.slice(0,2500)};
})()
